SELECT
ci.*
FROM ck_inventory ci
INNER JOIN (
SELECT
product_id,
MAX(created_at) as max_created_at
FROM ck_inventory
WHERE tenant_id = #{req.tenantId}
AND is_deleted = 0

    AND warehouse_id = #{req.warehouseId}


    AND product_id IN (
    SELECT id FROM product
    WHERE tenant_id = #{req.tenantId}
    AND product_name LIKE CONCAT('%', #{req.productName}, '%')
    )


    AND product_id IN (
    SELECT id FROM product
    WHERE tenant_id = #{req.tenantId}
    AND product_code LIKE CONCAT('%', #{req.productCode}, '%')
    )

GROUP BY product_id
) latest ON ci.product_id = latest.product_id
AND ci.created_at = latest.max_created_at
WHERE ci.tenant_id = #{req.tenantId}
AND ci.is_deleted = 0



        ORDER BY
        ci.created_at
        ci.quantity
        ci.product_id
        ${req.sortOrder}


        ORDER BY ci.created_at DESC




    LIMIT #{page.size} OFFSET #{page.current}

SELECT COUNT(DISTINCT product_id)
FROM ck_inventory
WHERE tenant_id = #{req.tenantId}
AND is_deleted = 0

    AND warehouse_id = #{req.warehouseId}


    AND product_id IN (
    SELECT id FROM product
    WHERE tenant_id = #{req.tenantId}
    AND product_name LIKE CONCAT('%', #{req.productName}, '%')
    )


    AND product_id IN (
    SELECT id FROM product
    WHERE tenant_id = #{req.tenantId}
    AND product_code LIKE CONCAT('%', #{req.productCode}, '%')
    )
